class Solution:
    def calculateScore(self, s: str) -> int:
        score = 0
        pos = [[] for _ in range(26)]

        for i, char in enumerate(s):
            c_idx = ord(char) - 97
            mirror_idx = 25 - c_idx

            if pos[mirror_idx]:
                j = pos[mirror_idx].pop()
                score += i - j
            else:
                pos[c_idx].append(i)

        return score
